package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.SelfRegistrationEnabledVO;

class SelfRegistrationEnabledValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of self registration enabled of tenant config")
  void test_self_registration_enabled_value_holder_assign_plain_value() {
    Object holder = new Object();
    SelfRegistrationEnabledValueHolder<Object> value =
        new SelfRegistrationEnabledValueHolder<>(holder);
    Assertions.assertSame(holder, value.selfRegistrationEnabled(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getSelfRegistrationEnabledValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getSelfRegistrationEnabled().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.selfRegistrationEnabledNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getSelfRegistrationEnabledValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of self registration enabled of tenant config")
  void test_self_registration_enabled_value_holder_assign_value_object() {
    Object holder = new Object();
    SelfRegistrationEnabledValueHolder<Object> value =
        new SelfRegistrationEnabledValueHolder<>(holder);
    SelfRegistrationEnabledVO vo = SelfRegistrationEnabledVO.from(true);
    Assertions.assertFalse(value.getSelfRegistrationEnabledValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.selfRegistrationEnabled(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getSelfRegistrationEnabledValue().orElseThrow());
    Assertions.assertSame(holder, value.selfRegistrationEnabled(Optional.empty()));
    Assertions.assertFalse(value.getSelfRegistrationEnabledValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.selfRegistrationEnabled(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSelfRegistrationEnabledValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of self registration enabled of tenant config against the original")
  void test_self_registration_enabled_value_holder_read() {
    Object holder = new Object();
    SelfRegistrationEnabledValueHolder<Object> value =
        new SelfRegistrationEnabledValueHolder<>(holder);
    SelfRegistrationEnabledVO vo = SelfRegistrationEnabledVO.from(true);
    SelfRegistrationEnabledVO other = SelfRegistrationEnabledVO.from(true);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getSelfRegistrationEnabledValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSelfRegistrationEnabled(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSelfRegistrationEnabled(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.selfRegistrationEnabled(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSelfRegistrationEnabled(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSelfRegistrationEnabled(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of self registration enabled of tenant config")
  void test_self_registration_enabled_value_holder_unset() {
    Object holder = new Object();
    SelfRegistrationEnabledValueHolder<Object> value =
        new SelfRegistrationEnabledValueHolder<>(holder);
    SelfRegistrationEnabledVO vo = SelfRegistrationEnabledVO.from(true);
    value.selfRegistrationEnabled(vo);
    Assertions.assertSame(holder,
        value.unsetSelfRegistrationEnabledIfMatches("selfRegistrationEnabled_other"));
    Assertions.assertTrue(value.getSelfRegistrationEnabledValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetSelfRegistrationEnabledIfMatches("selfRegistrationEnabled"));
    Assertions.assertFalse(value.getSelfRegistrationEnabledValue().isPresent(),
        "The field name must clear the value");
    value.selfRegistrationEnabled(vo);
    Assertions.assertSame(holder, value.unsetSelfRegistrationEnabled());
    Assertions.assertFalse(value.getSelfRegistrationEnabledValue().isPresent(),
        "Unset must clear the value");
  }
}
